function guessFeedback(secret, guess){ secret=+secret; guess=+guess; if(isNaN(guess)) return {error:'请输入数字'};
  if(guess===secret) return {result:'correct'}; return {result: guess<secret?'low':'high'}; }
function randomSecret(min,max,rng){ min=+min; max=+max; rng=rng||Math.random; if(!(max>min)) return {error:'范围无效'};
  return {value: Math.floor(rng()*(max-min+1))+min}; }
var EXPORTS={guessFeedback:guessFeedback, randomSecret:randomSecret};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.GuessForgePure = EXPORTS; }
